BEGIN
  p_Name_a0fc3c29696a := 'Sales: Party Lookup Accounts';
  p_CategoryID_a0fc3c29696a := '5A1E5000-0000-4000-A000-000000000001';
  p_UserQuestion_a0fc3c29696a := 'Which sales accounts start with what I have typed?';
  p_Description_a0fc3c29696a := 'Search for the Deal form''s account picker: sales accounts whose name, legal name, acronym or website domain starts with the term.';
  p_SQL_a0fc3c29696a := '-- Deal Account picker (bc-aidp-next-golive#372). Common''s "Common: Party Lookup Organizations" restricted
-- to organizations that have a SalesAccount row: Deal.AccountID points at SalesAccount, whose ID is the
-- Organization''s ID (IsA), so an organization without one cannot be stored.
--
-- Result contract shared by every party lookup query: ID, Name, Detail; parameters Term (required) and
-- Domain (optional, set by the picker when the term looks like a web address).
-- Prefix matches on indexed base columns only, TOP 20, no view, no count. sqlLikeBegins escapes %, _ and [ (and drops a trailing %).
-- Detail shows the acronym and the website domain ("NAR · nar.realtor"), whichever exist, so two accounts
-- with the same name or acronym can be told apart. Each operand goes through NULLIF so a stored empty string
-- is skipped like NULL (CONCAT_WS skips NULLs only).
SELECT TOP 20
    o.ID,
    o.Name,
    NULLIF(CONCAT_WS(N'' · '', NULLIF(o.Acronym, N''''), NULLIF(o.WebsiteDomain, N'''')), N'''') AS Detail
FROM [__mj_BizAppsCommon].Organization o
WHERE (
       o.Name      LIKE {{ Term | sqlLikeBegins }}
    OR o.LegalName LIKE {{ Term | sqlLikeBegins }}
    OR o.Acronym   LIKE {{ Term | sqlLikeBegins }}
    {% if Domain %}
    OR o.WebsiteDomain LIKE {{ Domain | sqlLikeBegins }}
    {% endif %}
)
  AND EXISTS (SELECT 1 FROM [__mj_BizAppsSales].SalesAccount sa WHERE sa.ID = o.ID)
ORDER BY o.Name, o.ID
';
  p_TechnicalDescription_a0fc3c29696a := 'Grain: Organization with a SalesAccount row (the IsA subtype Deal.AccountID references; subtype ID = Organization ID). Party lookup contract (bc-aidp-next-golive#372): columns ID, Name, Detail (Acronym and WebsiteDomain joined by '' · '', whichever are set); parameters Term (required) and Domain (optional; matched against Organization.WebsiteDomain). Prefix LIKE on indexed base columns (Name, LegalName, Acronym, WebsiteDomain), TOP 20 ordered by Name, no view and no count. Called by bizapps-party-field from @mj-biz-apps/common-ng.';
  p_Status_a0fc3c29696a := 'Approved';
  p_QualityRank_a0fc3c29696a := 8;
  p_ExecutionCostRank_a0fc3c29696a := 1;
  p_UsesTemplate_a0fc3c29696a := TRUE;
  p_AuditQueryRuns_a0fc3c29696a := FALSE;
  p_CacheEnabled_a0fc3c29696a := FALSE;
